import sys

def is_acyclic(graph, n):
    visited = [0] * n
    rec_stack = [0] * n

    def dfs(v):
        visited[v] = 1
        rec_stack[v] = 1
        for neighbor in graph[v]:
            if not visited[neighbor]:
                if dfs(neighbor):
                    return True
            elif rec_stack[neighbor]:
                return True
        rec_stack[v] = 0
        return False

    for node in range(n):
        if not visited[node]:
            if dfs(node):
                return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    edges = [(int(input[2 + 2 * i]) - 1, int(input[3 + 2 * i]) - 1) for i in range(m)]

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)

    for u, v in edges:
        graph[u].remove(v)
        if is_acyclic(graph, n):
            print("YES")
            return
        graph[u].append(v)

    print("NO")

main()
